#!/usr/bin/env bash
# SPDX-License-Identifier: Apache-2.0
#
# Structural integrity check for the published Evidence Theater Kill Suite.
#
# This is a MIRROR of a corpus generated by an upstream reference verifier; the
# authoritative gate (live appraisal of every fixture, plus the four-language
# byte-match) runs in that generator's repo. This check verifies only that the
# published mirror is internally complete and well-formed:
#
#   - every fixture is a complete triple (.aarp.json + .expect.json + .appraisal.json),
#   - SVID fixtures additionally carry a .svid.json sidecar,
#   - every JSON file parses,
#   - every expect.json declares verdict "appraise" (a kill-suite fixture never
#     makes an envelope fatal; it withholds claims),
#   - the corpus meets the published floor: >= 20 fixtures, >= 5 marked
#     pipelock_shaped with an overclaim refusal.
#
# Run: receipts/v0/evidence-theater/validate.sh
set -uo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
KS="$ROOT/killsuite"

[ -d "$KS" ] || { echo "FATAL: $KS missing" >&2; exit 2; }

python3 - "$KS" "$ROOT/trust.json" "$ROOT/test-keys.json" <<'PY'
import json, sys, glob, os

ks, trust, keys = sys.argv[1], sys.argv[2], sys.argv[3]
errors = []

def load(path):
    with open(path) as f:
        return json.load(f)

# Shared pinned material must parse.
for shared in (trust, keys):
    if not os.path.isfile(shared):
        errors.append(f"missing shared file: {os.path.basename(shared)}")
    else:
        try:
            load(shared)
        except Exception as e:
            errors.append(f"{os.path.basename(shared)}: invalid JSON: {e}")

total = 0
pipelock_downgrades = 0

def bases_for(suffix):
    return {
        os.path.basename(p)[: -len(suffix)]
        for p in glob.glob(os.path.join(ks, f"*{suffix}"))
    }

envelopes = bases_for(".aarp.json")
expects = bases_for(".expect.json")
appraisals = bases_for(".appraisal.json")
sidecars = bases_for(".svid.json")

for base in sorted(envelopes):
    if base not in expects:
        errors.append(f"{base}: missing {base}.expect.json")
    if base not in appraisals:
        errors.append(f"{base}: missing {base}.appraisal.json")
for base in sorted(expects - envelopes):
    errors.append(f"{base}: orphan expect.json without matching aarp.json")
for base in sorted(appraisals - envelopes):
    errors.append(f"{base}: orphan appraisal.json without matching aarp.json")
for base in sorted(sidecars - envelopes):
    errors.append(f"{base}: orphan svid.json without matching aarp.json")

for name in sorted(envelopes):
    base = os.path.join(ks, name)
    env = base + ".aarp.json"
    name = os.path.basename(base)
    total += 1
    expect_p = base + ".expect.json"
    appraisal_p = base + ".appraisal.json"
    for required in (env, expect_p, appraisal_p):
        if not os.path.isfile(required):
            errors.append(f"{name}: missing {os.path.basename(required)}")
    # Every JSON parses.
    for p in (env, expect_p, appraisal_p):
        if os.path.isfile(p):
            try:
                load(p)
            except Exception as e:
                errors.append(f"{os.path.basename(p)}: invalid JSON: {e}")
    if not os.path.isfile(expect_p):
        continue
    exp = load(expect_p)
    if exp.get("verdict") != "appraise":
        errors.append(f"{name}: verdict is {exp.get('verdict')!r}, kill-suite fixtures must be 'appraise'")
    if exp.get("fixture_id") != name:
        errors.append(f"{name}: fixture_id {exp.get('fixture_id')!r} does not match filename")
    # SVID sidecars are optional, but any sidecar that exists must parse and must
    # have a matching envelope (checked above).
    sidecar_p = base + ".svid.json"
    if os.path.isfile(sidecar_p):
        try:
            load(sidecar_p)
        except Exception as e:
            errors.append(f"{os.path.basename(sidecar_p)}: invalid JSON: {e}")
    if exp.get("pipelock_shaped") and (exp.get("must_not_verify") or exp.get("expected_overclaim_risks")):
        pipelock_downgrades += 1

if total < 20:
    errors.append(f"only {total} fixtures; the published floor is 20")
if pipelock_downgrades < 5:
    errors.append(f"only {pipelock_downgrades} reference-tool-shaped downgrades; the floor is 5")

if errors:
    print("FAIL: evidence-theater kill suite is not internally consistent:")
    for e in errors:
        print(f"  - {e}")
    sys.exit(1)

print(f"PASS: {total} fixtures well-formed ({pipelock_downgrades} reference-tool-shaped downgrades)")
PY
